from format_lecon import D,paras
from html import escape

def q(num,text):
 s=(D/f'evidence/AIPS_{num}.txt').read_text();assert text in s,(num,text)
 return '<blockquote><p>'+escape(text)+'</p></blockquote>'
def block(num,start,end):
 s=(D/f'evidence/AIPS_{num}.txt').read_text();i=s.index(start);return q(num,s[i:s.index(end,i)].strip())
def nasonex(l,polypes=False):
 body=paras('Furoate de mométasone, Nasonex, spray nasal ; autorisation Swissmedic 54189. Chaque pulvérisation apporte 50 µg. Les extraits suivants reproduisent l’information professionnelle suisse, y compris ses espacements de conversion.')
 if polypes:
  body+=paras('Polypes nasaux : adultes dès 18 ans. Posologie de la notice :')+block('54189','La dose recommandée est de 2 pulvérisations de spray 2×','Dans le cadre du traitement de la polypose')
  body+=q('54189',"La tolérance et l'efficacité de Nasonex n'ont pas été étudiées dans le traitement des polypes chez l'enfant et l'adolescent de moins de 18 ans.")
 else:
  body+=paras('Rhinite allergique : adultes, adolescents et enfants dès 12 ans :')+q('54189','1× par jour, de préférence le matin, 2 pulvérisations de spray dans c haque narine (correspond à 200 µg de furoate de mométasone/jour).')
  body+=q('54189',"Lorsque les symptômes sont sous contrôle, la dose peut être réduite à une dose d'entretien de 1× par jour 1 pulvérisation de spray dans chaque narine (correspond à 100 µg de furoate de momét asone/jour).")
  body+=paras('Enfants de 6 à 11 ans :')+q('54189','1× par jour 1 pulvérisation de spray dans chaque narine (correspond à 50 µg de furoate de mométasone/pulvérisation de spray ou 100 µg de furoate de mométasone/jour). Ne pas augmenter la posologie.')
  body+=paras('Cette indication suisse commence à six ans. Ne pas extrapoler aux plus jeunes ni à une hypertrophie adénoïdienne isolée.')
 body+=paras('Contre-indication :')+q('54189',"Hypersensibilité au principe actif ou à l'un des excipients conformément à la composition.")
 body+=paras('Éviter en cas d’infection nasale locale non traitée ; attendre la cicatrisation après traumatisme ou chirurgie. Surveiller muqueuse, épistaxis, croissance chez l’enfant au long cours et symptômes visuels. Une exposition systémique accrue est possible avec de puissants inhibiteurs du CYP3A4, notamment ritonavir ou cobicistat ; réévaluer l’association.', 'Grossesse et allaitement, extrait exact :')+q('54189',"Le traitement par des corticoïdes en application nasale pendant la grossesse et l'allaitement n'aura lieu qu'en cas d'absolue nécessité.")
 body+=paras('Le spray est un traitement de l’inflammation nasale dans son indication ; il ne constitue pas un traitement universel des apnées. Orienter le jet vers la paroi latérale, loin de la cloison, et expliquer l’usage régulier et l’effet différé.')
 return l.subwindow('nasonex','Mométasone nasale : indication, doses et sécurité AIPS',body,(18,9))
def euthyrox(l):
 body=paras('Lévothyroxine sodique, Euthyrox, comprimés sécables, autorisation Swissmedic 54949. Prescription individualisée après confirmation de l’hypothyroïdie ; les unités sont des microgrammes, pas des milligrammes.', 'Tableau AIPS, unité µg/jour, ligne hypothyroïdie :')+q('54949','Dose initiale: 25 à 50; augmentation à intervalles de 2 à 4 semaines, de 25 à 50 à chaque fois\nDose d\'entretien: 100 à 200')
 body+=q('54949','La dose journalière entière est prise le matin à jeun, au moins ½ heure avant le petit-déjeuner, sans croquer, avec un peu de liquide.')
 body+=paras('L’entretien indiqué n’est pas une cible obligatoire pour chaque patient. Chez les sujets âgés ou avec hypothyroïdie ancienne, sévère ou maladie cardiovasculaire, la notice recommande de commencer plus bas, à 25 µg, avec augmentation prudente et contrôles rapprochés. Une maladie cardiaque active peut constituer une contre-indication, et ne se résume pas à une réduction de dose.', 'Pédiatrie, extrait exact :')+q('54949','Les adolescents à partir de 12 ans reçoivent la même posologie que les adultes. Chez les enfants de moins de 12 ans, la posologie doit être déterminée de manière individuelle, car dans ce groupe, les doses nécessaires par kg de poids corporel sont plus élevées que chez l\'adulte.')
 body+=paras('Les schémas du nourrisson et de l’hypothyroïdie congénitale relèvent d’une prise en charge pédiatrique dédiée ; le tableau adulte ne leur est pas appliqué.', 'Contre-indications de la notice :')+block('54949','· insuffisance cardiaque accompagnée','Mises en garde et précautions')
 body+=paras('Une insuffisance surrénalienne doit être traitée avant la substitution thyroïdienne. Pour insuffisance hépatique ou rénale, la notice ne permet pas de recommander une adaptation chiffrée universelle ; individualiser.', 'Les sels de fer, calcium ou aluminium diminuent l’absorption ; la notice demande de prendre la lévothyroxine au moins deux heures avant. Les résines échangeuses d’ions nécessitent un intervalle plus long, de quatre à cinq heures. Vérifier aussi anticoagulants, antidiabétiques, inhibiteurs de pompe à protons et biotine.', 'Grossesse et allaitement :')+q('54949',"Pendant la grossesse et l'allaitement, il convient de continuer la prise d'hormones thyroïdiennes sans aucune interruption. Une dose plus élevée de lévothyroxine peut même s'avérer nécessaire en raison d'une augmentation de la concentration en globuline TBG fixant la thyroxine.")
 body+=q('54949',"La lévothyroxine ne passe qu'en très faibles quantités dans le lait maternel. Après l'administration de doses thérapeutiques, la concentration en lévothyroxine dans le lait maternel est trop faible pour provoquer une hyperthyroïdie ou inhiber la sécrétion de TSH chez le nourrisson. Par conséquent, Euthyrox peut être utilisé pendant l'allaitement.")
 body+=paras('La grossesse exige un suivi spécialisé rapproché et une adaptation après l’accouchement. La lévothyroxine n’est pas un médicament amaigrissant ni un traitement empirique d’un ronflement chez une personne euthyroïdienne.')
 return l.subwindow('euthyrox','Lévothyroxine : doses et précautions de la notice suisse',body,(19,16))
def sandostatine(l):
 body=paras('Octréotide, Sandostatine, solution injectable à libération immédiate, autorisation Swissmedic 49137. Ne pas confondre avec Sandostatine LAR, autre présentation et autre schéma. Utilisation spécialisée dans les indications de la notice, notamment échec ou impossibilité du traitement chirurgical ou relais en attente de l’effet de la radiothérapie.', 'Posologie AIPS pour l’acromégalie :')+block('49137','La dose initiale est de 0.05–0.1 mg','Voir aussi Sandostatine LAR')
 body+=paras('Le seuil de GH figurant dans cet extrait appartient à la notice ; les objectifs contemporains sont interprétés par le spécialiste avec l’IGF-1 rapporté à l’âge et au dosage utilisé. Ce schéma n’est pas une prescription pour le ronflement isolé.', 'Contre-indication :')+q('49137',"Hypersensibilité connue à l'octréotide ou à l'un des excipients.")
 body+=paras('Pédiatrie, extrait exact :')+q('49137',"Enfants et adolescents: pour ce groupe de patients, l 'expérience avec octréotide est encore limitée.")
 body+=paras('La cirrhose peut nécessiter une adaptation de l’entretien ; la notice ne demande pas d’adaptation rénale pour la voie sous-cutanée. Surveiller glycémie, fréquence cardiaque, fonction thyroïdienne et croissance tumorale. Une échographie vésiculaire est recommandée avant traitement puis tous les six à douze mois ; douleurs abdominales persistantes doivent faire rechercher une complication biliaire ou pancréatique.', 'Vérifier notamment antidiabétiques, bêtabloquants, ciclosporine, bromocriptine et traitements métabolisés par le CYP3A4 à marge étroite. Informer de la possibilité de restauration de fertilité et adapter la contraception.', 'Grossesse :')+q('49137',"Sandostatine ne doit être utilisé chez la femme enceinte qu'en cas de nécessité absolue.")
 body+=paras('Allaitement :')+q('49137',"Les patientes ne devraient pas allaiter pendant un traitement par Sandostatine.")
 body+=paras('La surveillance du sommeil reste nécessaire même si les valeurs hormonales s’améliorent. La sélection entre chirurgie, analogues, autres traitements endocriniens et radiothérapie appartient au centre hypophysaire.')
 return l.subwindow('sandostatine','Octréotide immédiat : exemple AIPS spécialisé',body,(20,15,17))
